<script lang="ts">
 import type {Preferences} from '../island/preferences';
 let {preferences:p,onupdate}:{preferences:Preferences;onupdate:(patch:Partial<Preferences>)=>void}=$props();
</script>
<div class="reader-settings">
 <div class="preview" style:text-align={p.lyricAlign} style:font-family={p.lyricFont==='serif'?'Georgia, serif':p.lyricFont==='rounded'?'Segoe UI Variable Text, sans-serif':'var(--font-sans)'} aria-label="Lyric style preview"><small>Let the day unfold</small><strong style:font-weight={p.lyricWeight} style:font-size={`${19*p.lyricScale}px`}>One moment at a time</strong><small>There is room to breathe</small></div>
 <label class="row"><span><strong>Reading layout</strong><small>All layouts fit inside the same island.</small></span><select aria-label="Lyric layout" value={p.lyricLayout} onchange={e=>onupdate({lyricLayout:e.currentTarget.value as Preferences['lyricLayout']})}><option value="spotlight">Spotlight</option><option value="balanced">Balanced three lines</option><option value="focus">Current line only</option></select></label>
 <label class="row"><strong>Typeface</strong><select aria-label="Lyric typeface" value={p.lyricFont} onchange={e=>onupdate({lyricFont:e.currentTarget.value as Preferences['lyricFont']})}><option value="sans">Original</option><option value="rounded">Soft</option><option value="serif">Serif</option></select></label>
 <label class="row"><strong>Alignment</strong><select aria-label="Lyric alignment" value={p.lyricAlign} onchange={e=>onupdate({lyricAlign:e.currentTarget.value as Preferences['lyricAlign']})}><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label>
 <label class="row"><span><strong>Text size <small class="inline">{Math.round(p.lyricScale*100)}%</small></strong><small>Long lines still shrink to fit and wrap.</small></span><input aria-label="Lyric text size" type="range" min=".7" max="1.4" step=".05" value={p.lyricScale} oninput={e=>onupdate({lyricScale:e.currentTarget.valueAsNumber})}/></label>
 <label class="row"><strong>Text weight</strong><input aria-label="Lyric text weight" type="range" min="400" max="800" step="50" value={p.lyricWeight} oninput={e=>onupdate({lyricWeight:e.currentTarget.valueAsNumber})}/></label>
 <label class="row"><strong>Line spacing</strong><select aria-label="Lyric line spacing" value={p.lyricSpacing} onchange={e=>onupdate({lyricSpacing:e.currentTarget.value as Preferences['lyricSpacing']})}><option value="compact">Compact</option><option value="comfortable">Comfortable</option><option value="airy">Airy</option></select></label>
 <label class="row"><strong>Surrounding lines</strong><select aria-label="Surrounding lyric emphasis" value={p.lyricContext} onchange={e=>onupdate({lyricContext:e.currentTarget.value as Preferences['lyricContext']})}><option value="dim">Dim</option><option value="soft">Soft</option><option value="clear">Clear</option></select></label>
 <label class="row switch"><span><strong>Animate lyric changes</strong><small>Flow to each line while keeping your place.</small></span><input role="switch" type="checkbox" checked={p.lyricFlow} onchange={e=>onupdate({lyricFlow:e.currentTarget.checked})}/></label>
 <label class="row switch"><span><strong>Word-by-word lyrics</strong><small>Fill each word as it is sung. Uses exact word timing when the source has it, otherwise an estimate across the line.</small></span><input aria-label="Word-by-word lyrics" role="switch" type="checkbox" checked={p.lyricWordSync} onchange={e=>onupdate({lyricWordSync:e.currentTarget.checked})}/></label>
 {#if p.lyricFlow}<label class="row"><span><strong>Transition duration</strong><small>{p.lyricFlowDuration} ms · short to gentle</small></span><input aria-label="Lyric transition duration" type="range" min="200" max="800" step="50" value={p.lyricFlowDuration} oninput={e=>onupdate({lyricFlowDuration:e.currentTarget.valueAsNumber})}/></label>{/if}
 <label class="row"><span><strong>Timing adjustment</strong><small>Positive shows lines earlier; negative delays them.</small></span><input aria-label="Lyric timing adjustment" type="number" min="-5" max="5" step=".1" value={p.lyricOffset} onchange={e=>onupdate({lyricOffset:Math.max(-5,Math.min(5,e.currentTarget.valueAsNumber||0))})}/></label>
 <button type="button" class="pill-btn" onclick={()=>onupdate({lyricLayout:'spotlight',lyricFont:'sans',lyricAlign:'left',lyricScale:1,lyricWeight:650,lyricSpacing:'comfortable',lyricContext:'dim',lyricFlow:false,lyricFlowDuration:420,lyricOffset:0})}>Reset lyric appearance</button>
</div>
<style>
 .reader-settings{font:var(--type-body)}.preview{padding:16px 18px;margin:8px 0 4px;border:1px solid #ffffff16;border-radius:14px;background:#ffffff05;overflow:hidden}.preview small{font-size:11px;opacity:.45;display:block}.preview strong{display:block;line-height:1.25;margin:6px 0}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;min-height:44px;border-bottom:1px solid #ffffff12}.row>span{min-width:0}.row strong{font-weight:560}.row small{display:block;font:var(--type-caption);opacity:.75;margin-top:3px}.row small.inline{display:inline}select,input[type=number]{color-scheme:dark;color:inherit;background:var(--surface-control);border:1px solid #ffffff20;border-radius:9px;min-height:30px;padding:4px 7px;font:var(--type-caption);max-width:150px}option{background:#24262d;color:#f5f5f5}input[type=number]{width:65px}input[type=range]{width:112px;flex:none;accent-color:var(--accent)}.switch input{appearance:none;width:34px;height:20px;flex:none;margin:0;border:0;border-radius:20px;background:oklch(.55 .01 255);position:relative;cursor:pointer}.switch input::before{content:"";position:absolute;width:14px;height:14px;top:3px;left:3px;border-radius:50%;background:var(--text-primary);transition:transform 160ms ease}.switch input:checked{background:var(--accent)}.switch input:checked::before{transform:translateX(14px);background:var(--on-accent)}.pill-btn{margin-top:12px}@media(prefers-reduced-motion:reduce){.switch input::before{transition:none}}
</style>
